const { execFileSync } = require('child_process');
const projectRoot = process.env.VIDEO_WORKFLOW_ROOT || 'D:\\抖音信息视频工作流';
const scriptPath = `${projectRoot}\\scripts\\prepare_next_task.js`;
const stdout = execFileSync(process.execPath, [scriptPath], { cwd: projectRoot, encoding: 'utf8', windowsHide: true, maxBuffer: 32 * 1024 * 1024, env: { ...process.env, VIDEO_WORKFLOW_ROOT: projectRoot } });
return [{ json: JSON.parse(stdout) }];

const result = $input.first().json;
return [{ json: {
  result: result.ready_for_next_stage ? '已准备下一条' : '当前没有待处理任务',
  message: result.message,
  next_task: result.next_task,
  queue: result.queue,
  library_sync: result.library_sync,
  voiceover_sync: result.voiceover_sync,
  prepared_at: result.prepared_at
} }];
